<?php defined('ABSPATH')||exit;$id=get_the_ID();$product=wc_get_product($id);$artist=gmr_theme_term_names($id,'gmr_artist')?:'Artista anónimo';$status=get_post_meta($id,'gmr_commercial_status',true)?:'available';?>
<article <?php post_class('gmr-card gmr-art-card');?>><a href="<?php the_permalink();?>"><div class="gmr-card__media"><?php if(has_post_thumbnail())the_post_thumbnail('large');else echo wc_placeholder_img('large');?><span class="gmr-art-card__view">Ver obra <i aria-hidden="true">↗</i></span></div><div class="gmr-card__meta"><div><p class="gmr-art-card__artist"><?php echo esc_html($artist);?></p><h2><?php the_title();?></h2><p><?php echo esc_html(trim(gmr_theme_year($id).(gmr_theme_term_names($id,'gmr_technique')?' · '.gmr_theme_term_names($id,'gmr_technique'):''),' ·'));?></p></div><span class="gmr-card__status gmr-card__status--<?php echo esc_attr($status);?>"><?php echo esc_html(gmr_theme_commercial_label($status));?></span></div><?php if(gmr_theme_can_view_price($id)):?><div class="gmr-card__price"><?php echo $product&&$product->get_price()?wp_kses_post($product->get_price_html()):esc_html(get_post_meta($id,'gmr_price_label',true)?:'Consultar');?></div><?php endif;?></a></article>
